INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('abandoned-chestnut-lodge-asylum', 34552, '2015-09-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/sogyidsyi5xbubkob49a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rmc4ulpsgfxz5pipxkr9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abandoned: Chestnut Lodge Asylum', 'These days the Chestnut Lodge Asylum is abandoned and forgotten, but many years ago a terrible tragedy unfolded behind those rusty gates. Every year, patients disappeared from the asylum without a trace. Neither the nurses nor the police could find any clues. But one day, everything changed. My dreams draw me to the asylum and I yearn to return to my normal life - a life without nightmares, premonitions, and fears.... Explore the Asylum and its surroundings, find out the true story of this place and face your fears in this gripping Hidden Object Puzzle Adventure!' FROM games WHERE igdb_id = 34552 ON CONFLICT (game_id, language_code) DO NOTHING;
