INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gary Grigsby''s War in the East', 'Gary Grigsby’s War in the East consists in a truly epic representation of the Second World War on the Eastern Front and is unparalleled in its scale, detail, and ambition. This game is the spiritual heir to the great Eastern Front board and computer wargames of the past; a turn-based World War II strategy game down to the division and brigade level, stretching across the entire Eastern Front at a 10 mile per hex scale.' FROM games WHERE igdb_id = 24627 ON CONFLICT (game_id, language_code) DO NOTHING;
