INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Amber Throne', 'Amber Throne is a traditional JRPG-styled game that focuses on turn-based battling and some light exploration. The game features a large cast of unique monsters that change stances depending on actions taken during combat, and a party with mostly mixed hybrid roles to deal with them. Learning monster behavior and how your skills affect them is essential to reaching victory.' FROM games WHERE igdb_id = 19517 ON CONFLICT (game_id, language_code) DO NOTHING;
