INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('red-game-without-a-great-name', 15038, '2015-07-27', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27wq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1iwr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Game Without a Great Name', 'Red Game Without a Great Name is a 2D puzzle arcade game where you control a mechanical bird carrying a secret message. Your goal is to deliver a letter to a recipient''s cage. You will have to face different traps along the way, including: barbed wire, windmill blades, spikes, and many others. Use the extraordinary power of teleportation to move your character through the level. Pick up power-ups to gain temporary abilities, like smashing walls, or invulnerability to damage. During your adventure collect gears to fully complete the game. Your journey will be a delight for your soul – the moody locations with the addition of a unique art style and swinging music will massage your senses.' FROM games WHERE igdb_id = 15038 ON CONFLICT (game_id, language_code) DO NOTHING;
