INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-last-crown-midnight-horror', 17206, '2015-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1j64.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar16ts.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Crown: Midnight Horror', 'Halloween: the veil between our world and the ''otherside'' is at its weakest. Witches celebrate Samhain, a Celtic festival from the old religion, conjuring the dead and communing with the spirits. Nigel Danvers, ghost-hunter, knows all about the ghosts that dwell in the darkness, he has seen plenty to convince him there are dark forces at work. So, why is Halloween so different? Dusting down his old ghost-hunting gadgets, Nigel gets to work. Something is haunting the guest rooms above the local harbour side pub, The Bear. Who or what hides in the shadowy corners of the old Inn? What is the presence at the end of the Harbour Wall? Nigel has one night to find out, before the veil returns to full strength, and the Halloween Horror is gone, for another year.' FROM games WHERE igdb_id = 17206 ON CONFLICT (game_id, language_code) DO NOTHING;
