INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('superbeat-xonic', 12875, '2015-10-22', 88, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27va.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbot.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superbeat: Xonic', 'SUPERBEAT: XONiC is an upcoming rhythm game developed by Nurijoy, a company formed by former employees of Pentavision. It is considered a spiritual successor to the DJMax music game series and its gameplay is based on the 2014 arcade game Beatcraft Cyclon, also made by Nurijoy. The gameplay of SUPERBEAT: XONiC consists of tapping notes to the beat of a song, either with the PlayStation Vita''s face buttons or touchscreen. Modes, in order of difficulty, include 4 TRAX mode, 6 TRAX, and 6 TRAX FX. When selecting any mode, 3 tracks are played in succession and the player''s performance is evaluated at the end. Local scores can be uploaded to a global online leaderboard if connected to the internet. SUPERBEAT will feature over 50 different tracks from a variety of genres, including soulful house, RnB, indie pop, progressive metal, and big beat and many more, and will include a collection of original music from producers such as 3rd Coast, ND Lee, Tsukasa and others.' FROM games WHERE igdb_id = 12875 ON CONFLICT (game_id, language_code) DO NOTHING;
