INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mordheim: City of the Damned', 'Mordheim: City of the Damned is the first video game adaptation of Games Workshop''s cult classic tabletop game Mordheim. Set in the Warhammer World''s decimated Empire city, Mordheim: City of the Damned is a turn-based tactical game where you lead warbands into bloody and lethal skirmishes. The game blends RPG elements, fast-paced tactical combat and intricate unit customization in a time wrought by chaos and rivalry where only the strongest survive.' FROM games WHERE igdb_id = 8209 ON CONFLICT (game_id, language_code) DO NOTHING;
