INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joe''s Diner', 'Somewhere along the venerable Route 7, in the middle of nowhere, you will find Joe’s Diner. The old Diner was built on the site of a former Indian cemetery. Amongst the buried, two rival chieftains are laid to rest; while alive each could not stand the other.' FROM games WHERE igdb_id = 35859 ON CONFLICT (game_id, language_code) DO NOTHING;
