INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA 2K16', 'The NBA 2K franchise is back with the most true-to-life NBA experience to date with NBA 2K16. Guide your MyPLAYER through the complete NBA journey, take control of an entire NBA franchise, or hone your skills online competing against gamers from around the world. With animations that provide smoother movement and more realistic articulation, it’s certain to be the most authentic NBA gaming experience yet.' FROM games WHERE igdb_id = 11525 ON CONFLICT (game_id, language_code) DO NOTHING;
