INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Beginner''s Guide', 'A metafictional account of Davey Wreden, creator of the Stanley Parable (2013), who takes the player through the games of his old friend, Coda, while giving his commentary and interpretations of them, in order to understand why he makes the bizarre, often melancholic games that he makes, and decipher Coda''s personality and inner struggles.' FROM games WHERE igdb_id = 13212 ON CONFLICT (game_id, language_code) DO NOTHING;
