INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield Hardline', 'Battlefield: Hardline features a whole new variety of gameplay that breaks away from the traditional Battlefield game modes. The new game modes are Heist Mode, Rescue Mode, Hotwire Mode and Bloodmoney Mode. The focus of the game has been shifted to police rather than the millitary background that has spanned the whole series up to now. Players will have access to various millitary grade weapons and vehicles as well as having police equipment such as tasers and handcuffs.' FROM games WHERE igdb_id = 7081 ON CONFLICT (game_id, language_code) DO NOTHING;
