INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Attack the Light!', 'A tactical role-playing video game based on the animated TV series Steven Universe and featuring a story written by series creator Rebecca Sugar. Join Steven and the three Crystal Gems—Garnet, Amethyst, and Pearl — as they travel across five color-themed worlds. Players move across the map by swiping the touchscreen and can interact with chests, mechanisms, and hidden areas to obtain items that can either be used in battle or to open up other areas. Some areas may be inaccessible until players solve a puzzle or obtain the necessary item from another level.' FROM games WHERE igdb_id = 22555 ON CONFLICT (game_id, language_code) DO NOTHING;
