INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ori and the Blind Forest', 'The forest of Nibel is dying. After a powerful storm sets a series of devastating events in motion, an unlikely hero must journey to find his courage and confront a dark nemesis to save his home. Ori and the Blind Forest tells the tale of a young orphan destined for heroics, through a visually stunning action-platformer crafted by Moon Studios for Xbox One and PC. Featuring hand-painted artwork, meticulously animated character performance, and a fully orchestrated score, Ori and the Blind Forest explores a deeply emotional story about love and sacrifice, and the hope that exists in us all.' FROM games WHERE igdb_id = 7344 ON CONFLICT (game_id, language_code) DO NOTHING;
