INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'N++', 'N++ is a fast-paced, action-packed platformer set in the distant future. You play as a ninja, darting through obstacles, narrowly evading a slew of inadvertently homicidal enemy robots and collecting gold in a minimalist, sci-fi world. N++ is all about smooth physics, deftly controlling the speed and inertia of the character, and the awesome feeling of fluidly moving through each level.' FROM games WHERE igdb_id = 8750 ON CONFLICT (game_id, language_code) DO NOTHING;
