INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grapple', 'Grapple is a 3D puzzle platformer. You can fling, swing and climb across everything in Grapple. Different surfaces react uniquely to your gooball. Grapple is as fast paced as you want to play it. With multiple checkpoints and unlimited lives your skill is the only thing slowing you down.' FROM games WHERE igdb_id = 12878 ON CONFLICT (game_id, language_code) DO NOTHING;
