INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Falls: Legend of the Gnome Gemulets', 'Gravity Falls: Legend of the Gnome Gemulets is a side-scrolling platform game. Players assume control of Dipper and Mabel, and they can freely switch between them at any moment during the game. The two characters have different abilities. Dipper can combat enemies with a close-ranged weapon called Gnome Battle Cuffs and look for clues using a flashlight, while Mabel can utilize a grappling hook to reach high grounds, and combat enemies with ranged attacks by her "Fleece of Bedazzlement-enhanced sweater sleeves".' FROM games WHERE igdb_id = 44014 ON CONFLICT (game_id, language_code) DO NOTHING;
