INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tinertia', 'In this game you must master the skill of rocket-jumping to traverse expansive, maze-like environments. Tinertia''s platforming mechanics are entirely physics-based, giving you immense freedom of movement. There''s no top speed and you can keep adding to your momentum. Launch yourself over deadly obstacles, take on bossy robots, and ultimately escape off the planet - Weldon''s survival depends on it!' FROM games WHERE igdb_id = 18012 ON CONFLICT (game_id, language_code) DO NOTHING;
