INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Best Fiends Forever', 'Get ready for the very big adventure with very small heroes! The sequel to the award-sometimes-winning-and-if-not-we''re-just-happy-to-be-nominated Best Fiends! But it''s nothing like that game! Except that it''s got the same characters, and you''re still beating up slugs. But it''s a clicker adventure, which is different, and we think a lot of fun!' FROM games WHERE igdb_id = 57363 ON CONFLICT (game_id, language_code) DO NOTHING;
