INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City of Chains', 'City of Chains is a dark sci-fi RPG set in a dystopian city. Take control of a small group of escaped fugitives and lead them to their freedom. Decide whether to fight head on or to avoid combat, to help others or to go your own way, to show mercy or to kill. Your actions could affect the fate of the city.' FROM games WHERE igdb_id = 34177 ON CONFLICT (game_id, language_code) DO NOTHING;
