INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fort Meow', 'Fort Meow is a pillow fort physics-based puzzle adventure involving cats, destruction and a dusty old manor. Upon finding her grandfather''s journal in the attic, Nia is attacked by a barrage of feline assailants. It seems that her grandmother has become a crazy cat lady since last time she visited, so you will need to defend Nia by building a protective fort out of furniture to keep the cats at bay, while deciphering the mysterious tales hidden within the journal.' FROM games WHERE igdb_id = 11246 ON CONFLICT (game_id, language_code) DO NOTHING;
