INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Dance 2016', 'Just Dance brings the best hits like “Blame” by Calvin Harris Ft. John Newman and “Uptown Funk” by Marc Ronson Ft. Bruno Mars to dance and sing along to, with the usual golden treasures like “Let’s Groove” by Equinox Stars that makes Just Dance a must-have to play with friends and family! No additional device is required, with the free Just Dance Controller App to play and use your smartphone as a controller! Discover Just Dance Unlimited, the new subscription streaming service to play your favorite hits from past Just Dance games (accessible on Wii U, PS4, XboxOne).' FROM games WHERE igdb_id = 11206 ON CONFLICT (game_id, language_code) DO NOTHING;
