INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout 4', 'Bethesda Game Studios welcome you to the world of Fallout 4, their most ambitious game ever, and the next generation of open-world gaming. As the sole survivor of Vault 111, you enter a world destroyed by nuclear war. Every second is a fight for survival, and every choice is yours. Only you can rebuild and determine the fate of the Wasteland. Welcome home.' FROM games WHERE igdb_id = 9630 ON CONFLICT (game_id, language_code) DO NOTHING;
