INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Pizza Girl', 'Ninja Pizza Girl is a supreme platformer with a deep-dish message. Set in a technicolour dystopia, this high-speed adventure about bullying, resilience and pizza delivery is a fast-paced parkour platformer that responds to your success. Fight to keep your ideals, your family and their business intact in face of the most merciless enemies known to any teenage girl – other teenagers.' FROM games WHERE igdb_id = 18336 ON CONFLICT (game_id, language_code) DO NOTHING;
