INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crossfire: Dungeons', 'Battle against rival fantasy armies in this fast paced turn based strategy game. Fight powerful bosses while you hunt for treasure in dungeon mode, play through over one hundred single player missions in campaign mode, or match wits against your friends in multiplayer. Simple one-click per unit control scheme takes minutes to learn, while the in-depth army building and game strategy keeps you coming back for more. 6 different armies to master each with unique units, strengths and play styles.' FROM games WHERE igdb_id = 35262 ON CONFLICT (game_id, language_code) DO NOTHING;
