INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saga', 'Build cities, command troops, and manage resources like in a traditional RTS, and also go on quests, chat with your friends, join guilds, and trade like an MMO. SAGA is an MMORTS with battling similar to the Total War series, mixed with city building from Stronghold. Build your army by collecting cards found in booster packs, or trade in-game resources for them in the auction house.' FROM games WHERE igdb_id = 21484 ON CONFLICT (game_id, language_code) DO NOTHING;
