INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rory McIlroy PGA Tour', 'Rory McIlroy PGA Tour is an upcoming golf video game under development by EA Tiburon. First announced at E3 2014 under the working title EA Sports PGA Tour, it is expected to be released in June 2015. The game will mark the franchise''s shift to PlayStation 4 and Xbox One, adopting the Frostbite 3 engine for more "lifelike" environments, and is also the first entry in EA Sports'' PGA Tour series to not feature Tiger Woods as its namesake, replacing him with current World Number One Rory McIlroy.' FROM games WHERE igdb_id = 9651 ON CONFLICT (game_id, language_code) DO NOTHING;
