INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Decisive Campaigns: The Blitzkrieg from Warsaw to Paris', 'Decisive Campaigns: The Blitzkrieg from Warsaw to Paris is the first in an innovative series of operational World War II wargames that also include a strategic element. The Blitzkrieg from Warsaw to Paris simulates Germany’s military successes in Poland and France in 1939 and 1940 (including also a hypothetical “Sea Lion” invasion of Great Britain if you do well enough).' FROM games WHERE igdb_id = 36053 ON CONFLICT (game_id, language_code) DO NOTHING;
