INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zenzizenzic', 'Zenzizenzic hurls you into the abstract perils of a bullet-strewn fever dream. Battle your way through five varied levels in Classic Mode or explore an open world in Macro Mode, both of which are stuffed to the brim with legions of enemies. You''ll dodge an onslaught of bullets while returning fire with an awesome arsenal of weapons and power-ups, leaving complete and utter destruction in your wake.' FROM games WHERE igdb_id = 17924 ON CONFLICT (game_id, language_code) DO NOTHING;
