INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alphadia Genesis 2', 'While claiming to protect its citizens, the Empire has launched a ruthless campaign against the Atramian population—those said to be infected with black energi and whose existence they deem to be a threat to the world. Discover the true face of evil in this next chapter of the Alphadia series, a story filled with belief, sacrifice, revenge, and ultimately hope!' FROM games WHERE igdb_id = 38988 ON CONFLICT (game_id, language_code) DO NOTHING;
