INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Minifigures Online', 'LEGO Minifigures Online is an online game for LEGO fans of all ages, where you get to collect awesome Minifigures, build your own unique team and go on exciting adventures through classic LEGO worlds! Smash your enemies with your awesome guitar riffs as the Rock Star, or transform yourself into a spider with Spooky Girl! There are over one hundred Minifigures to collect and play with in LEGO Minifigures Online! You can even use codes found in real Minifigures bags to unlock and play with them in-game!' FROM games WHERE igdb_id = 17874 ON CONFLICT (game_id, language_code) DO NOTHING;
