INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword Art Online: Lost Song', 'Journey into the world of Alfheim Online for the very first time! Join Kirito as he ventures online to explore Svart Alfheim, a brand-new area of ALfheim Online, the floating world is comprised of continents led by The Floating City of Ryne. This original storyline includes new and returning characters and exclusive environments in the ultimate Virtual Reality universe! Sword Art Online: Lost Song features all-new Aerial Battles and plenty of customization features. Link Start into the Sword Art Online world and join your favorite dual-wielding player, Kirito, on the greatest adventure yet!' FROM games WHERE igdb_id = 11842 ON CONFLICT (game_id, language_code) DO NOTHING;
