INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zodiac: Orcanon Odyssey', 'Zodiac: Orcanon Odyssey is a role-playing game featuring gorgeous hand-drawn 2D art, a beautiful soundtrack and a deep storyline created by an international team that includes iconic Final Fantasy developers. The game is as engaging as it is stylish, offering classic elements from Japanese RPGs that can be enjoyed alone or together.' FROM games WHERE igdb_id = 24604 ON CONFLICT (game_id, language_code) DO NOTHING;
