INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ray Gigant', 'Ray Gigant is a Japanese dungeon-crawling role-playing game. The stage of Ray Gigant is set in June of year 20xx, where the world has been destroyed by a giant creature known as the "gigant" that suddenly appeared on the planet. In battle, your party is made of three members. Unlike other dungeon-crawlers by Experience, the perspective in combat will show the backside of the characters.' FROM games WHERE igdb_id = 11743 ON CONFLICT (game_id, language_code) DO NOTHING;
