INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlazBlue: Central Fiction', 'BlazBlue: Central Fiction is a 2D fighting game developed by Arc System Works. It is the fourth game to the BlazBlue series, and is set after the events of BlazBlue: Chrono Phantasma. The game adds Naoto Kurogane and Hibiki Kohaku as playable characters. BlazBlue: Central Fiction marks the conclusion of the story surrounding protagonist Ragna the Bloodedge.' FROM games WHERE igdb_id = 11613 ON CONFLICT (game_id, language_code) DO NOTHING;
