INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'God of War III: Remastered', 'Set in the realm of brutal Greek mythology, God of War III Remastered is the critically acclaimed single-player game that allows players to take on the fearless role of the ex-Spartan warrior, Kratos, as he rises from the darkest depths of Hades to scale the very heights of Mount Olympus to seek his bloody revenge. Armed with double-chained blades and an array of new weapons and magic, Kratos must take on mythology’s deadliest creatures while solving intricate puzzles throughout his merciless quest to destroy Olympus.' FROM games WHERE igdb_id = 19959 ON CONFLICT (game_id, language_code) DO NOTHING;
