INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kung Fu Panda: Showdown of Legendary Legends', 'The lovable martial arts panda bear, Po, and his many friends and adversaries in the Valley of Peace will face off in the ultimate martial arts challenge ... the first-ever Kung Fu Panda: Showdown of Legendary Legends! Kung Fu Panda: Showdown of Legendary Legends will bring fans a fresh and fist-pumping way to experience DreamWorks Animation''s beloved franchise with explosive, fast-as-lightning action! With a variety of challenging multiplayer levels, familiar film locations and 20 playable fan-favorite Kung Fu Panda characters, the game will appeal to gamers who like their brawler games served up with a side of laughter.' FROM games WHERE igdb_id = 20089 ON CONFLICT (game_id, language_code) DO NOTHING;
