INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Vikings', 'Embark on a dead funny adventure with the Zombie Vikings. A putrid posse sent on a mission through the most epic of worlds to retrieve Odin’s lost eye. Play as the most fearsome Vikings ever raised from Norse soil: Gunborg, Seagurd, Hedgy and Caw-kaa. Hack through the gingerbread swamps of Molgaga! Cruise through the intestines of the Midgaard Serpent! Fight giant poultry!' FROM games WHERE igdb_id = 14298 ON CONFLICT (game_id, language_code) DO NOTHING;
