INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fairway Solitaire - Card Game', 'Fairway Solitaire combines classic solitaire with golf course themes across over 1,000 levels. Players clear cards by selecting cards one rank higher or lower, aiming for long streaks to earn bonuses. The game features three modes (Main, Daily, and Bonus), daily events, and strategic power-ups like Shuffle, Preview, and Mulligan cards. Progress saves across devices through account login, and offline play is supported with later syncing.' FROM games WHERE igdb_id = 86795 ON CONFLICT (game_id, language_code) DO NOTHING;
