INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Hunter 5', 'Dungeon Hunter 5, stylised in the logo as Dungeon Hunter V, is a 2015 mobile hack and slash role-playing game developed and published by Gameloft. It was released on February 27, 2015 for iOS, Android and Windows Phone devices. The game serves as a direct sequel to Dungeon Hunter 4 which ended amidst the dying Valenthia city state. Dungeon Hunter 5 is an online game that requires an internet connection in order to play.' FROM games WHERE igdb_id = 39217 ON CONFLICT (game_id, language_code) DO NOTHING;
