INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam: Extreme Vs Force', 'Take control of the most powerful Mobile Suits and lead your forces to victory! It is a portable spin-off of the Extreme Vs. series, developed by Bandai Namco Entertainment for Playstation Vita. The game was initially released in 23 December 2015 in Japan, while localized Chinese and English editions were released in Asia during the following year in January and February respectively. On 12 July 2016, it was released in North America, Europe, Africa, Australasia, and the Middle East as a digital-only title on the Playstation Network, and includes all DLC and updates from its Japanese version.' FROM games WHERE igdb_id = 20401 ON CONFLICT (game_id, language_code) DO NOTHING;
