INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock Band 4', 'Rock Band, the award-winning social and interactive music performance experience, is back! Form your own band, rock the world, and live out your ultimate rock and roll fantasy, with your friends, family, or as a solo act. Rock Band 4 delivers the ultimate platform for gamers to experience music, giving players the chance to rock in the shoes of the biggest guitarists, bassists, drummers, and singers of all time. Rock Band 4 delivers the most authentic music game ever, challenging rockers to master lead guitar, bass guitar, drums, and vocals.' FROM games WHERE igdb_id = 10128 ON CONFLICT (game_id, language_code) DO NOTHING;
