INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VRC Pro', 'VRC Pro takes you deep into the world of cutting edge, modern RC cars. You can race up to 15 different RC cars on real existing mini race tracks all around the world; all fully customizable & tunable. With top speeds of around 120 km/h (75 Mph) and insane acceleration on ultra tight tracks; get ready to experience a whole new level of racing!' FROM games WHERE igdb_id = 36141 ON CONFLICT (game_id, language_code) DO NOTHING;
