INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bombernauts', 16627, '2015-06-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ca9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/h6dvswalooanq8wk4wcx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bombernauts', 'Bombernauts is an explosive online multiplayer battle game with fully destructible voxel terrain. Throw stupid amounts of bombs to blow your robot friends off the world into the deadly lava below where they will surely die a fiery death! If that doesn''t work, whack open a few piñatas with your trusty baseball bat, grab some overpowered powerups (like jetpacks, black holes, missiles, luchador masks, and more), and win that way instead! Do whatever it takes to be the last bot standing and claim your well deserved victory!' FROM games WHERE igdb_id = 16627 ON CONFLICT (game_id, language_code) DO NOTHING;
