INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Party 10', 'Mario Party 10 has tons of fun new ways to play, challenge, and triumph over your friends, with new modes and a wealth of other exciting goodies. Strategize your way around a variety of unique boards to gather coins and stars, and best your buddies. In Bowser Party mode, you can take the role of bad guy Bowser to mess with your friends’ game. Need to let off some steam? Challenge your friends to a bunch of exciting minigames, unlock bonus content, and more.' FROM games WHERE igdb_id = 7340 ON CONFLICT (game_id, language_code) DO NOTHING;
