INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloodborne', 'An action RPG in which the player embodies a Hunter who, after being transfused with the mysterious blood local to the city of Yharnam, sets off into a "night of the Hunt", an extended night in which Hunters may phase in and out of dream and reality in order to thin the outbreak of abominable beasts that plague the land and, for the more resilient and insightful Hunters, uncover the answers to the Hunt''s many mysteries.' FROM games WHERE igdb_id = 7334 ON CONFLICT (game_id, language_code) DO NOTHING;
