INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Tri Force Heroes', 'The Legend of Zelda: Tri Force Heroes is the direct sequel to The Legend of Zelda: A Link Between Worlds. The game is similar to the Four Swords games in which Link is accompanied by two other Links in the game''s multiplayer mode, but it also allows for a single-player mode in which the other Links are replaced by animated dolls that can be swapped out during the game. The three Link can cooperate in a variety of ways to solve puzzles and coordinate their attacks with the help of on-screen notifications that give clues on what to do.' FROM games WHERE igdb_id = 11194 ON CONFLICT (game_id, language_code) DO NOTHING;
