INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom vs. The Armies of Hell', 'Tom vs. the Armies of Hell (AoH for short) is a challenging indie Action-Adventure game from Darkmire Entertainment. Set in a world somewhere between Office Space and Army of Darkness, you play Tom, a down-trodden software-engineer turned reluctant half-demon hero when an experiment gone awry in the basement government lab sends his entire office complex plummeting into Hell.' FROM games WHERE igdb_id = 16827 ON CONFLICT (game_id, language_code) DO NOTHING;
