INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saints Row: Gat Out of Hell', 'After the space faring antics of Saints Row IV, many fans asked what we could do next… the answer? Shoot The Devil in the face. Play as either Johnny Gat or Kinzie Kensington as you tear apart Hell in a quest to save the leader of the Saints’ soul. Historical icons, old friends, older enemies, a talking gun, a full length musical number, and a whole lot of other shenanigans all await you in the open world standalone expansion playground that is Saints Row: Gat Out Of Hell.' FROM games WHERE igdb_id = 7708 ON CONFLICT (game_id, language_code) DO NOTHING;
