INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hand of Fate', 'Inspired by tarot and fantasy, all bets are off as you create your own journey by building a collection of cards used to deal out a boardgame-like dungeon teeming with enemies, treasure, and adventure. Upon entering combat, the cards come to life as the player is propelled into a beautiful 3D environment to brawl it out with foes. Draw your cards, play your hand, and discover your fate.' FROM games WHERE igdb_id = 9101 ON CONFLICT (game_id, language_code) DO NOTHING;
