INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Total Extreme Wrestling 2010', 'Step into the world of wrestling in Total Extreme Wrestling 2010. In this simulation title, you play the role of a wrestling promoter, and it is up to you to steer your company to the top of the industry! You are in control of everything - deal with superstar egos, negotiate through wars and alliances with other wrestling promotions, and deal with the demands of TV networks. Do you have what it takes to lead your wrestling promotion to the top of the industry?' FROM games WHERE igdb_id = 35871 ON CONFLICT (game_id, language_code) DO NOTHING;
