INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choice Chamber', 'A crowd-sourced action game designed for livestreaming where viewers play along via the chat to change the game in realtime as you play. Players constantly give feedback that changes how the game evolves, from power ups and enemies to obstacles and rule changes. The game world is procedurally generated based on viewer input, wildly changing the difficulty and surprises each time you play.' FROM games WHERE igdb_id = 22036 ON CONFLICT (game_id, language_code) DO NOTHING;
