INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Downwell', 'Downwell is a curious game about a young man with guns for boots venturing down a well in search of untold treasures. Make your way further and further down into a darkness filled with nasty creatures and mysterious secrets and collect the spectacular red gems scattered about the rocks. Step into an oddly placed shop to buy some helpful items or level up between caverns to battle well dwelling monsters and uncover hidden caves filled with riches and relics. No two trips down the well are ever the same!' FROM games WHERE igdb_id = 13677 ON CONFLICT (game_id, language_code) DO NOTHING;
