INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nitroplus-blasterz-heroines-infinite-duel', 13552, '2015-04-30', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yyu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfpw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nitroplus Blasterz: Heroines Infinite Duel', 'Nitroplus Blasterz: Heroines Infinite Duel is a fighting game which crosses over heroines from various visual novels and games released by Nitroplus, as well as those from manga and anime series that Nitroplus writers have been involved with. The game uses five buttons; light attack, medium attack, heavy attack, escape action, and heavy action. The escape action button can be used to perform evasive maneuvers and guards while heavy actions can be used to push an opponent back. Players can perform Infinite Blasts, which can interrupt an opponent''s attack, Variable Rushes, which allows for surprise combos, and Lethal Blazes, which serve as the game''s super combo attacks. Players can also choose two support characters which they can summon to assist them.' FROM games WHERE igdb_id = 13552 ON CONFLICT (game_id, language_code) DO NOTHING;
