INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Opus: The Day We Found Earth', 'Opus: The Day We Found Earth is a stargazing experience handcrafted for people who enjoy story driven games and arguing about Pluto. After eons of spreading across the cosmos, humanity has lost its way back. Help the childlike robot Emeth carry on his creator''s will of finding our long lost home, and peer into a forgotten galaxy through the lens of a deep space telescope.' FROM games WHERE igdb_id = 18900 ON CONFLICT (game_id, language_code) DO NOTHING;
