INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Tactics', 'X-Tactics is an episodic Turn Based RPG updated weekly, that is also a location-based game that uses player location and local weather to affect the tactical conditions of missions, which combines turn-based tactical gameplay with an original fighting game inspired combo/command skill system, and mechanics to create a new style of gameplay. In it you control a rag-tag team of secret agents who protect the World and the Truth.' FROM games WHERE igdb_id = 19482 ON CONFLICT (game_id, language_code) DO NOTHING;
