INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Templar Battleforce', 'Step into the pilot suit of a Leviathan mech and lead the Templar Knights in battle against fierce enemies. Create your own unique Battleforce by recruiting an array of Templar specialists and then design their exact build of equipment and talents. Invent distinct strategies and fire teams that guarantee no two armies will be the same. Deploy your forces into tactical scenarios that will challenge both novice and veterans alike.' FROM games WHERE igdb_id = 13217 ON CONFLICT (game_id, language_code) DO NOTHING;
