INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Fear 2: The Chaos Lord', 'Age of Fear 2: The Chaos Lord is a refreshingly fun strategy title that marries a tabletop wargame with elements of RPG. The game features a huge variety of units, a novel hex-free battle system, morale, and multiplayer. Play as a manipulative succubuss or a brutal orc warchief in two story driven campaigns!' FROM games WHERE igdb_id = 35992 ON CONFLICT (game_id, language_code) DO NOTHING;
