INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbow Six Siege', 'Inspired by the reality of counter terrorist operatives across the world, Rainbow Six Siege invites players to master the art of destruction. Intense close quarters confrontations, high lethality, tactics, team play, and explosive action are at the center of the experience. The multiplayer gameplay of Rainbow Six Siege sets a new bar for intense firefights and expert strategy in the rich legacy of past Rainbow Six games.' FROM games WHERE igdb_id = 7360 ON CONFLICT (game_id, language_code) DO NOTHING;
