INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby and the Rainbow Curse', 'Do you have the magic touch? Then guide Kirby as he sets off on grand adventures in a hand-sculpted clay world. Draw lines on the touch screen of the Wii U GamePad controller to create rainbow-colored clay ropes to move Kirby around freely, or tap him to attack enemies or blast through obstacles. Transformations include a submarine, rocket and tank. In underwater levels, Kirby dons a swim mask. If his power level gets too low, a clay bandage appears on his head.' FROM games WHERE igdb_id = 7338 ON CONFLICT (game_id, language_code) DO NOTHING;
