INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rack N Ruin', 'Chaos reigns in this top down action adventure game starring Rack, a demon with an appetite for destruction. Pave a path of mayhem as you guide Rack on his quest to jump start the Apocalypse. Wield powerful magic, decimate your foes, unravel mind bending puzzles, and smite titanic bosses all while corrupting a vast open world.' FROM games WHERE igdb_id = 12216 ON CONFLICT (game_id, language_code) DO NOTHING;
