INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Idolmaster: Cinderella Girls - Starlight Stage', 'The Idolmaster: Cinderella Girls Starlight Stage is an upcoming spin-off free-to-play rhythm game released for mobile devices based on The Idolmaster: Cinderella Girls. The game revolves around tapping icons of the idols in the rhythm of the background song. Different kinds of notes will be brought in to show how each icon must be tapped; these include simply tapping the icon, tapping and holding down the icon, and tapping two icons simultaneously.' FROM games WHERE igdb_id = 11711 ON CONFLICT (game_id, language_code) DO NOTHING;
