INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('particle-mace', 17304, '2015-01-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pqv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bktfh1lb0ibp39hq4bkj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Particle Mace', 'Particle Mace is explosive arcade fun for 1-4 players that pays homage to twitch games of the past, but replaces the typical guns with an unruly physics-based weapon. Take control of a tiny ship in an extremely hostile universe, and defend yourself as long as possible from enemy ships and asteroids using a collection of trash particles tethered to the ship. To survive, you must carefully navigate around the many hazards while building up momentum to swing your weapon into your foes or your friends, all in a field of brightly abstracted visuals and an entrancing procedural background.' FROM games WHERE igdb_id = 17304 ON CONFLICT (game_id, language_code) DO NOTHING;
