INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sym', 'Sym is a puzzle-platformer that explores social anxiety disorder. Play as Josh, a teenage boy trying to reconcile a maze of two contrasting worlds that coexist within the blank spaces of each other - his perception of reality, and the world he created to avoid his fears.' FROM games WHERE igdb_id = 11424 ON CONFLICT (game_id, language_code) DO NOTHING;
