INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Savage Lands', 'A New Land, A New Life: Savage Lands is a gritty, brutal, first-person open-world fantasy survival experience in which players have only one goal: Stay Alive. Explore a world where days and nights are spent slaughtering vicious creatures, gathering scarce resources, building shelter and crafting powerful weapons needed to survive. Every decision counts, because one mistake can lead to an unfortunate encounter with death''s cold embrace.' FROM games WHERE igdb_id = 17548 ON CONFLICT (game_id, language_code) DO NOTHING;
