INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster High: New Ghoul in School', 'Come roam the halls of Monster High and get to know your new classmates. Join clubs, make friends and dress up in fierce fashions. But be aware, there’s something strange going on at Monster High! Cleo’s new amulet has been cursed by the spirit of Spookenhamen, and the student body is falling under his spell. Show us how you boo to save the school and all your new classmates from the mummy’s curse!' FROM games WHERE igdb_id = 19318 ON CONFLICT (game_id, language_code) DO NOTHING;
