INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spelunker World', '"In SPELUNKER WORLD, players take the role of a Spelunker, following in the footsteps of his father who disappeared 10 years ago. Players can venture into caverns solo or together with up to six players online in search of legendary treasures while avoiding dangerous pitfalls, boulders and wicked creatures. Hidden within every nook and cranny are various power ups and unlocks to customize characters’ skills and appearances. The title offers an array of adorable pets that aid players as they uncover deeper and dangerous caves."' FROM games WHERE igdb_id = 21587 ON CONFLICT (game_id, language_code) DO NOTHING;
