INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Party Hard', 'Party Hard is a tactical game about stopping parties. Playing as someone who got sick of neighbors having loud parties, you decide to take matters into your own hands with the help of your faithful knife. The story follows a series of mass murders around the USA, with parties taking place in various locations including Las Vegas, Miami, San Francisco, and more.' FROM games WHERE igdb_id = 12070 ON CONFLICT (game_id, language_code) DO NOTHING;
