INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob HeroPants', 'SpongeBob HeroPants is an action game with a focus on platforming, exploration, light puzzles and combat. Each of its six playable characters–SpongeBob, Patrick, Squidward, Sandy, Mr. Krabs and Plankton–can morph into a unique superpowered champion to solve challenges, unlock new areas and defeat SpongeBob''s crazy imagination. The full adventure features boss battles, upgradeable skills and a treasure trove of hidden items to unearth.' FROM games WHERE igdb_id = 8474 ON CONFLICT (game_id, language_code) DO NOTHING;
