INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('assassins-creed-chronicles-china--1', 8223, '2015-04-21', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qy6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4yu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed Chronicles: China', 'Chronicles: China takes place after the film Assassin''s Creed: Embers. It features the Chinese assassin Shao Jun in 1526. After being trained by legendary Italian assassin Ezio Auditore da Firenze, Shao Jun returns to her homeland to exact vengeance against the Templar group Eight Tigers, who wiped out the Chinese brotherhood. Shao Jun''s quest took her through Macau, Nan''an, the Forbidden City and the Great Wall, as she killed the Tigers one by one and finally assassinating the final target, Zhang Yong. Years later, Shao Jun, who became an Assassin Mentor and had rebuilt the brotherhood, plotted the assassination of Jiajing Emperor by sending him an elixir of life.
