INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Age of Decadence', 'The Age of Decadence is an upcoming pseudo-isometric 3D turn-based role-playing video game for Windows, Mac OS X and Linux by Iron Tower Studio, led by the pseudonymous "Vince D. Weller". Set in a low-magic, post-apocalyptic world inspired by the fall of the Roman Empire, The Age of Decadence aims to return to the ''golden era'' of RPGs by emphasizing choices and consequences and providing a comprehensive skill set, multiple solutions to quests, and extensive dialogue trees.' FROM games WHERE igdb_id = 4641 ON CONFLICT (game_id, language_code) DO NOTHING;
