INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pathologic Classic HD', 'In Pathologic players embark on a dark journey to explore a remote town built upon old tanneries and butcheries just as a mysterious and deadly disease breaks out. Pathologic Classic HD is an extensive remaster of the original game, featuring updated graphics and effects, while addressing the most prominent critiques of the original with a completely redone English script, brand new re-recorded voice-overs and reinstated text and dialogue.' FROM games WHERE igdb_id = 13204 ON CONFLICT (game_id, language_code) DO NOTHING;
