INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Static Speaks My Name', 'A dark/sad/weird/funny first person exploration game. You play a man on his last night alive as he obsesses over a mysterious painting. More of a story game in that it emphasizes mood and character over gameplay. Takes ten minutes to play and has "next-gen" features like a shrimp tank.' FROM games WHERE igdb_id = 11765 ON CONFLICT (game_id, language_code) DO NOTHING;
