INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alter World', 'Inspired by Stephen King’s book - “The Dark Tower”, Alter World is a 2D platformer with interesting gameplay mechanics. Player can pass on an alternative universe anytime and use an alternative realms to move to another level. Levels are unique, with puzzles. player will have to react quickly and assess when to move between the Worlds. The game is made in unique art style, like a painting.' FROM games WHERE igdb_id = 35588 ON CONFLICT (game_id, language_code) DO NOTHING;
