INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('westerado-double-barreled', 8904, '2015-04-16', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/qi8xefnkistp4kbk0ms4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6tr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Westerado: Double Barreled', 'Westerado: Double Barreled is Ostrich Banditos'' homage to Spaghetti Westerns about dirty pasts, consequences and taking a hold of your future. When your family is murdered by a mysterious desperado, you set out into the world to take revenge. Take control of your own fate and that of others, all using your trusty shooting iron. If words aren''t enough to persuade a character, draw your revolver and see what happens. You can shoot whomever, whenever you like. Be an outlaw or a saint, explore the open world, meet a varied cast of characters and decide how you want your revenge story to unfold.' FROM games WHERE igdb_id = 8904 ON CONFLICT (game_id, language_code) DO NOTHING;
