INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ADOM: Ancient Domains of Mystery', 'ADOM is an epic fantasy Roguelike. The story takes you to the Drakalor Chain, a mountainous area in the fictional land of Ancardia. You are a lone wanderer whose purpose is to find the source of the Chaos spreading throughout the land. Pursuing your quest you traverse through dark dungeons and untamed wilds where death lurks around every corner.' FROM games WHERE igdb_id = 36159 ON CONFLICT (game_id, language_code) DO NOTHING;
