INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Port of Call', 'Imagine waking up on a small dock with no recollection of who you are or how you got there. The first person you find is a grumpy, old man who enlists you to work on his ferry boat which seems to have materialized behind you. But not all is as it seems on this strange ship, and the people you meet may know more about your past than they let on.' FROM games WHERE igdb_id = 35598 ON CONFLICT (game_id, language_code) DO NOTHING;
