INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minecraft: Story Mode', 'Minecraft: Story Mode is a five-part adventure series based on the sandbox building and exploration game Minecraft. Typical for Telltale games, it is a cinematic adventure where the story is driven through the player''s choices. Decisions are carried over and influence characters and events. The game uses the original title''s block design and introduces a story for the game world as there was none for the original title. At the start of the game the player can choose between six characters, three male and three female, with different appearances.' FROM games WHERE igdb_id = 8339 ON CONFLICT (game_id, language_code) DO NOTHING;
