INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('solarix', 17146, '2015-03-04', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1o6y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zogxuyyrcbp9jsa4enyt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solarix', 'Solarix is a science-fiction stealth-horror game featuring open-ended levels for both combative and stealth-focused playstyles. Solarix combines old-school sci-fi horror with next-gen style and graphics. The story follows an electrical engineer desperately fighting for his life after an infection wipes out an interstellar research station. He must contain the disease, battling both the remnants of the crew and his own fracturing mind. Our goal is to go beyond jumpscares and cheap thrills. Solarix is about a world that overpowers you with unease, insecurity, and desperation, forcing you to confront your own role in the horrors to come.' FROM games WHERE igdb_id = 17146 ON CONFLICT (game_id, language_code) DO NOTHING;
