INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Default Dan', 'Coins make you explode? Spikes make you bounce! All of this is normal in the world of Default Dan, a new indie platformer that flips the genre upside-down by making every object in the game do the opposite of what it appears. By using the player’s own instincts against them, Default Dan aims to provide a humorous, mind-bending experience that gamers of all ages can enjoy.' FROM games WHERE igdb_id = 24032 ON CONFLICT (game_id, language_code) DO NOTHING;
