INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One More Dungeon', 'One More Dungeon is a first person shooter roguelike with procedurally generated levels and pixel-art graphics. Being a nameless adventure seeker, you have to get to the final level of the dungeon and destroy the obelisks, which is being used by forces of Evil to invade the world. Use a melee weapon, magic staffs, and antique artefacts, to burst way through the hordes of enemies inhabiting a few game areas.' FROM games WHERE igdb_id = 14764 ON CONFLICT (game_id, language_code) DO NOTHING;
