INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paperbound', 'Run with scissors and walk on walls in this award-winning local-multiplayer gravity battle arena game from the mind of a former Call of Duty: Advanced Warfare developer. Enter the pages of old books where you will find strange environments and a cabal of playable characters. Matches are not only fast-paced and intense, but they require you to think in whole new ways in order to master gravity.' FROM games WHERE igdb_id = 21849 ON CONFLICT (game_id, language_code) DO NOTHING;
