INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goosebumps: The Game', 'The walk home from school today is going to be a lot spookier than usual… Your sleepy neighborhood’s been overrun by monsters! Werewolves prowl the woods, Gnomes roam underfoot, and scarecrows walk at midnight. But these aren’t ordinary monsters—they’re R.L. Stine’s famous Goosebumps monsters, released from their books and looking to wreak havoc!' FROM games WHERE igdb_id = 23472 ON CONFLICT (game_id, language_code) DO NOTHING;
