INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-escapists-the-walking-dead--1', 11744, '2015-09-30', 64, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co233x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6re.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Escapists: The Walking Dead', 'Manage your escape from an onslaught of walkers in this cross-over between the time management escape game The Escapists and the blockbuster zombie franchise The Walking Dead. Using the retro graphical style of The Escapists, the game gives you control of Rick Grimes as he tries to secure the safety of a number of familiar characters by seeking out a safe escape route from each area, fending off the zombie hordes and keeping as many of them alive as possible as they escape. The game will faithfully keep to the timeline of the comics, so as you progress you''ll move through a series of familiar locations.' FROM games WHERE igdb_id = 11744 ON CONFLICT (game_id, language_code) DO NOTHING;
