INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Undertale', 'A small child falls into the Underground, where monsters have long been banished by humans and are hunting every human that they find. The player controls the child as they try to make it back to the Surface through hostile environments, all the while engaging with a turn-based combat system with puzzle-solving and bullet hell elements, as well as other unconventional game mechanics.' FROM games WHERE igdb_id = 12517 ON CONFLICT (game_id, language_code) DO NOTHING;
