INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Why Am I Dead At Sea', 'Why Am I Dead At Sea is an adventure game where you solve the mystery of your own murder.  As a ghost, you will have to possess people and use them to investigate your surroundings.  But in this place no one is who they seem...and everyone has a secret.' FROM games WHERE igdb_id = 35525 ON CONFLICT (game_id, language_code) DO NOTHING;
