INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broforce', 'When evil threatens the world, the world calls on Broforce - an under-funded, over-powered paramilitary organization dealing exclusively in excessive force. Brace your loins with up to four players to run ‘n’ gun as dozens of different bros and eliminate the opposing terrorist forces that threaten our way of life. Unleash scores of unique weapons and set off incredible chain reactions of fire, napalm, and limbs in the name of freedom.' FROM games WHERE igdb_id = 5973 ON CONFLICT (game_id, language_code) DO NOTHING;
