INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timber and Stone', 'Timber and Stone is a voxel-based sandbox city building game with a heavy emphasis on combat, fortifications, and siege warfare. While you build your humble village into a mighty castle town, you will be bombarded with waves of monsters that are either working together or fighting amongst each other.' FROM games WHERE igdb_id = 24518 ON CONFLICT (game_id, language_code) DO NOTHING;
