INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Dinos', 'Play Bad Dinos – a new kind of tower-defense game that makes the rest feel ancient! Protect the Poundrok family while rescuing its adventurous son from the clutches of a high-flying pterodactyl. Junior Poundrok yearned to fly but not like this. Now his family must pile into its rockin’ Winnecavo to retrieve him while guarding against incoming stampedes of ill-tempered dinosaurs!' FROM games WHERE igdb_id = 23219 ON CONFLICT (game_id, language_code) DO NOTHING;
