INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Xanadu', 'Tokyo Xanadu is an action RPG that blends dungeon crawling with high school life simulation. By day, you''re a student in modern Tokyo building relationships and enjoying school activities. By night, you''re pulled into Eclipse, a nightmarish alternate realm where you battle creatures born from human negative emotions. Master fast-paced real-time combat with elemental strategies and character switching, then return to strengthen bonds with classmates who fight alongside you with unique abilities.' FROM games WHERE igdb_id = 11455 ON CONFLICT (game_id, language_code) DO NOTHING;
