INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fingered', 'GUILTY! THEY ARE ALL GUILTY! FINGERED is a "whodunit" hyperrealisic police sim where you must finger the guilty and clean up this darn city using the descriptions of the local busy bodies. but everyone''s perspective is different: one man''s fat is another man''s sexy! send him to the chair!!!' FROM games WHERE igdb_id = 11742 ON CONFLICT (game_id, language_code) DO NOTHING;
