INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pike and Shot: Campaigns', 'Pike and Shot is a turn-based tactical game, set in a time where musketeers “gave fire” in a duel to the death, pikemen held stolidly against enemy assaults, and cavalry charged to glory or defeat. You can take command in the greatest historical battles of the Italian Wars (1494-1559 A.D.), the Thirty Years War (1618-1648 A.D.) and the English Civil War (1642-1651 A.D.). Pike and Shot Campaigns includes the Pike and Shot base game and the Tercio to Salvo expansion.' FROM games WHERE igdb_id = 35035 ON CONFLICT (game_id, language_code) DO NOTHING;
