INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Live 16', 'Elevate your game to the highest level with NBA LIVE 16, the most complete NBA basketball experience. With enhanced user control that increases the realism of gameplay on both ends of the court, utilize the fundamentals of basketball to dominate the boards, fill the lane, and run the point as the most dominant player in the league.' FROM games WHERE igdb_id = 11074 ON CONFLICT (game_id, language_code) DO NOTHING;
