INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sovereignty: Crown of Kings', 'The old Empire is crumbling. Younger hungrier realms wait like vultures for their chance to pick at the carcass. Thus begins the grand campaign of Sovereignty. Rule your realm wisely and decisively. Play as the Boruvian Empire and try to recapture former Imperial glories. Or play any of 34 other realms, each with their own rich history, culture and play-style.' FROM games WHERE igdb_id = 17613 ON CONFLICT (game_id, language_code) DO NOTHING;
