INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luna''s Wandering Stars', 'An action puzzle game that utilizes real physics to present interesting and challenging cosmic puzzles. Use a variety of powers to control planetary movements, such as changing gravity, designating velocity, applying force, and using mysterious wormholes to move masses around. The goal of every level is to collect enough asteroids using moons to move on to the next level. For a real challenge, collect the rare golden asteroids in every level!' FROM games WHERE igdb_id = 17983 ON CONFLICT (game_id, language_code) DO NOTHING;
