INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unloved', 'Unloved is based on the community award-winning mod for Doom2 with the same name by the same creator. Unloved is a strange place. A twisted reality. A nightmare that comes to life. A place where demons and abhorrent monsters manifest and possess the living with only one goal: to end you. Nothing wants you here. And there is no way out. Only the elevator that leads further and further down into the darkness of your insanity.' FROM games WHERE igdb_id = 17799 ON CONFLICT (game_id, language_code) DO NOTHING;
