INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty Online', 'Call of Duty Online is a Call of Duty game released exclusively in China as a free-to-play micro transaction game. The game features a new gaming model which gives the player the ability to personalize weapons, characters and equipment with localized, unique content tailored to the needs and interest of gamers in China. The game also reuses dozens of maps, character models and weapons from both the Modern Warfare and Black Ops series, which can be seen in its trailers. Ghosts and Advanced Warfare contents have also been added.' FROM games WHERE igdb_id = 77289 ON CONFLICT (game_id, language_code) DO NOTHING;
