INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wander', 'Ever wonder what sort of secrets are hidden amongst nature? Now''s your chance to find out. Soar through the skies, swim the depths of the ocean, and explore the lush rainforests in Wander, the non-combat explorative-based indie MMO. Slow moving and relaxing, with lots of trees and no explosions.' FROM games WHERE igdb_id = 10920 ON CONFLICT (game_id, language_code) DO NOTHING;
