INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('omega-labyrinth', 11548, '2015-11-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co61ib.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/eeiv6rztsktm3ylwwdsc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omega Labyrinth', 'Omega Labyrinth is an upcoming roguelike RPG developed by Matrix Software for the Playstation Vita. One of the systems in the game is the Omega Power. The embodiment of womanly strength, Omega Power is power which is stored in your chest – but also amounts to experience points. By gaining Omega Power through defeating monsters in the dungeon you can increase the size of your chest – with a jump in cup size also powering up your abilities. Another important system in the game is the “Faint in Agony Awakening” system, which you can use to strengthen your status and acquire new abilities. By using a “Faint in Agony Aroma” item found in a dungeon, you can excite one of the character and have her experience various delusions. By touching her during these delusions, her Omega Power and status will increase – with sensitive spots differing by character and situation.' FROM games WHERE igdb_id = 11548 ON CONFLICT (game_id, language_code) DO NOTHING;
