INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Troma Project', 'The Troma Project is the exciting turn based strategy game which puts you in the world of Troma and Toxic Mayhem! Featuring The Toxic Avenger, Sgt. Kabukiman N.Y.P.D. and Super Tromette Tiffany Shepis, Toxic Mayhem is the fun and addictive game which allows players to mindlessly kill anything and everything that moves! And, at the beginning of every mission, Lloyd Kaufman will give you advice on how to get through it! Toxic Mayhem is the greatest video game since Toxic Crusaders for the Sega Genesis and Nintendo.' FROM games WHERE igdb_id = 17092 ON CONFLICT (game_id, language_code) DO NOTHING;
