INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Reavers', 'LOST REAVERS is an intense four-player co-op game where players must discover hidden treasures at the end of a series of dungeons and haul it safely back to their extraction point while their friends protect them. Along the way, the team will encounter a variety of traps, clever foes and the dungeon bosses who will do everything in their power to thwart the quartet. Through all of these challenges, one of the brave four must bring the treasure hoard safely back home by using only their wits and their friends to survive.' FROM games WHERE igdb_id = 8595 ON CONFLICT (game_id, language_code) DO NOTHING;
