INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Statues', 'Do not even try to close your eyes. You can''t let the fear go. It is real. It is more real than you can imagine... "Statues" is a mix of survival-horror and action-adventure developed by Room710Games. The game based on the creepy enemies that only move when you''re not looking at them.' FROM games WHERE igdb_id = 26519 ON CONFLICT (game_id, language_code) DO NOTHING;
